572	    html += '<div class="contingency"><h4>⚠ Contingency</h4><p>'+st.contingency+'</p></div>';
573	  }
574	
575	  // action row
576	  html += '<div class="action-row">';
577	  if(viewing){
578	    html += '<button class="btn primary" id="back-current">Return to current step</button>';
579	  } else if(!done){
580	    html += '<button class="btn" id="back-btn" '+(S.currentIdx===0?"disabled":"")+'>Back</button>';
581	    if(st.irreversible){
582	      html += '<button class="btn danger" id="execute-btn" '+(gatesOk?"":"disabled")+'>Execute “'+st.title+'”…</button>';
583	    } else {
584	      html += '<button class="btn primary" id="complete-btn" '+(gatesOk?"":"disabled")+'>Mark step complete</button>';
585	    }
586	    html += '<span class="action-note">'+(gatesOk?"All gates passed — you may proceed.":"Complete every gate above to unlock this action.")+'</span>';
587	  } else {
588	    html += '<button class="btn" id="back-btn">Back</button>';
589	    if(S.currentIdx<RUNBOOK.steps.length-1){
590	      html += '<button class="btn primary" id="advance-btn">Continue → next step</button>';
591	    } else {
592	      html += '<button class="btn primary" id="finish-btn">Finish runbook</button>';
593	    }
594	  }
595	  html += '</div>';
596	  w.innerHTML = html;
597	
598	  // wire events
599	  w.querySelectorAll('input[type=checkbox][data-gate]').forEach(cb=>{
600	    cb.addEventListener("change", onCheck);
601	  });
602	  w.querySelectorAll("button[data-verify]").forEach(b=>{
603	    b.addEventListener("click", ()=>onVerify(st.id, b.dataset.verify));
604	  });
605	  const bind=(id,fn)=>{ const el=$("#"+id,w); if(el) el.addEventListener("click",fn); };

605	  const bind=(id,fn)=>{ const el=$("#"+id,w); if(el) el.addEventListener("click",fn); };
606	  bind("complete-btn", ()=>completeStep(st));
607	  bind("execute-btn", ()=>openModal(st));
608	  bind("advance-btn", advance);
609	  bind("finish-btn", finish);
610	  bind("back-btn", ()=>{ if(S.viewIdx!==S.currentIdx){S.viewIdx=S.currentIdx;renderAll();} else if(S.currentIdx>0){S.viewIdx=S.currentIdx-1;renderAll();} });
611	  bind("back-current", ()=>{ S.viewIdx=S.currentIdx; renderAll(); });
612	  bind("rollback-btn", ()=>rollback(st));
613	  if(S.lastFocusId){ const el=document.getElementById(S.lastFocusId); if(el) el.focus(); S.lastFocusId=null; }
614	}
615	
616	/* ---------- header ---------- */
617	function renderHeader(){
618	  const done = RUNBOOK.steps.filter(s=>S.status[s.id]==="done").length;
619	  const total = RUNBOOK.steps.length;
620	  $("#prog-num").textContent = done+" / "+total+" steps";
621	  $("#prog-fill").style.width = (100*done/total)+"%";
622	  const bar=$("#prog-track"); bar.setAttribute("aria-valuenow", String(done));
623	}
624	
625	/* ---------- gate interactions ---------- */
626	function onCheck(e){
627	  const cb=e.target, gid=cb.dataset.gate, i=+cb.dataset.item;
628	  const st=RUNBOOK.steps[S.viewIdx!==S.currentIdx?S.viewIdx:S.currentIdx];
629	  const g=st.gates.find(x=>x.id===gid), gs=S.gate[st.id][gid];
630	  gs.items[i]=cb.checked;
631	  cb.closest(".gate-item").classList.toggle("checked",cb.checked);
632	  const item=g.items[i];
633	  if(cb.checked) audit("gate","Checked — <b>"+item.label+"</b> ("+g.label+")");
634	  const all=gs.items.every(Boolean);
635	  if(all && !gs.passed){
636	    gs.passed=true; audit("ok","Gate passed — <b>"+g.label+"</b> ("+st.title+")");
637	  } else if(!all && gs.passed){ gs.passed=false; }
638	  // targeted update: chip on this gate card + action button (keeps keyboard focus)
639	  const chip=cb.closest(".gate-card").querySelector(".gate-state");
640	  if(all){ chip.className="gate-state pass"; chip.textContent="PASSED"; }
641	  else { chip.className="gate-state pending"; chip.textContent="PENDING"; }
642	  refreshActionButton(st);
643	}
644	function refreshActionButton(st){
645	  const btn=$("#complete-btn")||$("#execute-btn");
646	  if(btn) btn.disabled = !allGatesPassed(st);
647	  const note=$(".action-note");
648	  if(note) note.textContent = allGatesPassed(st) ? "All gates passed — you may proceed." : "Complete every gate above to unlock this action.";
649	}
650	function onVerify(stepId, gid){
651	  const st=stepBy(stepId), g=st.gates.find(x=>x.id===gid), gs=S.gate[stepId][gid];
652	  const input=document.getElementById("vf-"+gid);
653	  gs.input=input.value;
654	  if(norm(input.value)===norm(g.field.expected)){
655	    gs.verified=true; gs.failed=false; S.verifications++;
656	    audit("ok","Verified — <b>"+g.field.label+"</b> = "+input.value.trim()+" ("+st.title+")");
657	  } else {
658	    gs.failed=true; S.warnings++;
659	    audit("danger","Verification FAILED — <b>"+g.field.label+"</b> “"+input.value.trim()+"” does not match expected. Contingency opened. ("+st.title+")");
660	  }
661	  S.lastFocusId = gs.verified ? null : ("vf-"+gid);
662	  renderAll();
663	}
664	function completeStep(st){
665	  S.status[st.id]="done";
666	  audit("ok","<b>Step completed</b> — "+st.title+" (reversible; may be revisited)");
667	  renderAll();
668	}
669	function advance(){
670	  if(S.currentIdx<RUNBOOK.steps.length-1){ S.currentIdx++; S.viewIdx=S.currentIdx; renderAll(); }
671	}
672	function finish(){
673	  S.completed=true;
674	  audit("ok","<b>Runbook complete</b> — CHG-2417 closed. "+S.audit.length+" events recorded.");
675	  renderAll();
676	}
677	
678	/* ---------- modal ---------- */
679	function openModal(st){
680	  S.modalStepId=st.id; S.lastFocusId="execute-btn";
681	  $("#m-title").textContent=st.title;
682	  $("#m-desc").textContent=st.desc;
683	  $("#m-blast").innerHTML="<b>Blast radius:</b> "+st.confirm.blast;
684	  $("#m-rec").innerHTML="<b>"+st.confirm.recTitle+"</b><ol style='margin:4px 0 0;padding-left:20px'>"+st.confirm.rec.map(r=>"<li>"+r+"</li>").join("")+"</ol>";
685	  $("#m-phrase-label").textContent='Type “'+st.confirm.phrase+'” to confirm you understand this is irreversible:';
686	  const inp=$("#m-phrase"); inp.value=""; inp.className="";
687	  $("#m-execute").disabled=true;
688	  $("#confirm_modal").classList.add("open");
689	  inp.focus();
690	}
691	function closeModal(){
692	  $("#confirm_modal").classList.remove("open");
693	  S.modalStepId=null;
694	  if(S.lastFocusId){ const el=document.getElementById(S.lastFocusId); if(el) el.focus(); }
695	}
696	function wireModal(){
697	  const inp=$("#m-phrase");
698	  inp.addEventListener("input", ()=>{
699	    const st=stepBy(S.modalStepId);
700	    $("#m-execute").disabled = !(st && norm(inp.value)===norm(st.confirm.phrase));
701	  });
702	  inp.addEventListener("keydown", e=>{
703	    if(e.key==="Enter" && !$("#m-execute").disabled) executeModal();
704	  });
705	  $("#m-cancel").addEventListener("click", ()=>{ audit("gate","Confirmation cancelled — no action taken (safe)"); closeModal(); });
706	  $("#m-execute").addEventListener("click", executeModal);
707	  $("#confirm_modal").addEventListener("click", e=>{ if(e.target===$("#confirm_modal")) closeModal(); });
708	  document.addEventListener("keydown", e=>{ if(e.key==="Escape" && S.modalStepId) closeModal(); });
709	}
710	function executeModal(){
711	  const st=stepBy(S.modalStepId); if(!st) return;
712	  S.confirmations++;
713	  audit("danger","Typed confirmation matched — <b>"+st.confirm.phrase+"</b>");
714	  S.status[st.id]="done";
715	  audit("danger","<b>Irreversible action executed</b> — "+st.title);
716	  if(st.undoWindowSec){
717	    S.undo={stepId:st.id, endsAt:Date.now()+st.undoWindowSec*1000};
718	    audit("recovery","Undo window opened — <b>"+fmtClock(st.undoWindowSec)+"</b> for "+st.title+". Rollback stays available.");
719	  }
720	  closeModal();
721	  renderAll();
722	}
723	function rollback(st){
724	  if(!S.undo || S.undo.stepId!==st.id) return;
725	  S.undo=null;
726	  S.status[st.id]="pending";
727	  // later steps collapse back to pending
728	  const idx=RUNBOOK.steps.indexOf(st);
729	  RUNBOOK.steps.forEach((s,i)=>{ if(i>idx && S.status[s.id]==="done") S.status[s.id]="pending"; });
730	  S.currentIdx=idx; S.viewIdx=idx;
731	  audit("recovery","<b>Rolled back</b> — "+st.title+". Traffic repointed to 2.3.9; window closed; step awaits re-execution.");
732	  renderAll();
733	}
734	setInterval(()=>{
735	  if(S && S.undo){
736	    const left=Math.ceil((S.undo.endsAt-Date.now())/1000);
737	    const clock=document.getElementById("undo-clock");
738	    if(clock) clock.textContent=fmtClock(Math.max(0,left));
739	    if(left<=0){
740	      const st=stepBy(S.undo.stepId);
741	      S.undo=null;
742	      audit("recovery","Undo window closed — "+st.title+". Only the documented recovery path applies now.");
743	      renderAll();
744	    }
745	  }
746	},1000);
747	
748	/* ---------- misc ---------- */
749	function copyAudit(){
750	  const text=S.audit.map(e=>"["+e.t+"] "+e.kind.toUpperCase()+" — "+e.html.replace(/<[^>]+>/g,"")).join("\n");
751	  const done=n=>{ const b=$("#copy-audit"); b.textContent=n; setTimeout(()=>b.textContent="Copy audit log",1600); };
752	  if(navigator.clipboard && navigator.clipboard.writeText){
753	    navigator.clipboard.writeText(text).then(()=>done("Copied ✓")).catch(()=>fallback());
754	  } else fallback();
755	  function fallback(){
756	    const ta=document.createElement("textarea"); ta.value=text; document.body.appendChild(ta);
757	    ta.select(); try{document.execCommand("copy"); done("Copied ✓");}catch(e){done("Copy failed");} ta.remove();
758	  }
759	}
760	function renderAll(){ renderHeader(); renderRail(); renderWork(); renderAudit(); }
761	
762	/* rail clicks (delegated) */
763	$("#phase_step_rail").addEventListener("click", e=>{
764	  const btn=e.target.closest(".step-row"); if(!btn) return;
765	  if(btn.classList.contains("locked")){
766	    btn.classList.remove("deny"); void btn.offsetWidth; btn.classList.add("deny");
767	    return;
768	  }
769	  const idx=RUNBOOK.steps.findIndex(s=>s.id===btn.dataset.step);
770	  S.viewIdx=idx; renderAll();
771	});
772	
773	/* ---------- boot: usable at first paint, data inlined ---------- */
774	initState();
775	wireModal();
776	renderAll();
777	</script>
778	</body>
779	</html>
