let n=0;
RUNBOOK.phases.forEach((ph,pi)=>{
  const rows = RUNBOOK.steps.filter(s=>s.phase===ph.id);
  html += '<div class="phase-label"><span class="ph-idx">PHASE '+(pi+1)+'</span> '+ph.name+'</div>';
  rows.forEach(st=>{
    const idx=n++; const cls=stepStatus(st,idx);
    const irrev = st.irreversible ? '<span class="st-flag">IRREV</span>' : '';
    let mark="·";
    if(cls==="done") mark="✓";
    if(cls==="current") mark=String(idx+1);
    const clickable = cls==="done"||cls==="current";
    html += '<button class="step-row '+cls+(S.status[st.id]==="recovered"?" irrev-done":"")+'" data-step="'+st.id+'" '+
      (clickable?"":'aria-disabled="true" title="Locked until earlier steps complete"')+
      ' aria-current="'+(cls==="current"?"step":"false")+'">'+
      '<span class="st-idx">'+(idx+1)+'</span><span class="st-name">'+st.title+'</span>'+irrev+
      '<span class="st-mark" aria-hidden="true">'+mark+'</span></button>';
  });
});

